                    OperandIndex = 2,
                },
                new GasEvaluatorInstructionBlob
                {
                    Opcode = GasEvaluatorOpcode.PushValueView,
                },
                new GasEvaluatorInstructionBlob
                {
                    Opcode = GasEvaluatorOpcode.Subtract,
                },
                new GasEvaluatorInstructionBlob
                {
                    Opcode = GasEvaluatorOpcode.PushConstant,
