                new GasTargetDataDescriptorBlob { Variant = GasTargetDataVariant.StableAsc, FieldOrdinal = 0, Required = 1 },
                new GasTargetDataDescriptorBlob { Variant = GasTargetDataVariant.StableAsc, FieldOrdinal = 0, Required = 1 },
